{% if var('m_MT_RSTD_BKGS_BY_WEEK_mt_rstd_bkgs_by_week_product_sql_override', '') != '' %}
{{ var('m_MT_RSTD_BKGS_BY_WEEK_mt_rstd_bkgs_by_week_product_sql_override') }}
{% else %}
-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
FD2Y.FISCAL_YEAR_WEEK_NUM_INT BK_FISCAL_YEAR_WEEK_NUM_INT,
FD2Y.FISCAL_YEAR_MONTH_INT FISCAL_YEAR_MTH_NUM_INT,
BKGS_MSR.PRODUCT_KEY,
BKGS_MSR.SALES_TERRITORY_KEY,
BKGS_MSR.SALES_REP_NUMBER SALES_REP_NUM,
BKGS_MSR.WIPS_ORIGINATOR_ID_INT AS DISTRIBUTOR_ID,
BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE BKGS_MEASURE_TRANS_TYPE_CD,
BKGS_MSR.CANCEL_CODE CANCEL_CD,
BKGS_MSR.SALESREP_FLG,
BKGS_MSR.SERVICE_FLG,
CASE
WHEN BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG IS NULL
THEN 'N' ELSE BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG
END AS CHANNEL_BOOKINGS_FLG,
CASE
WHEN BKG_CHNL_MSR.CHANNEL_DROP_SHIP_FLG IS NULL
THEN 'N' ELSE BKG_CHNL_MSR.CHANNEL_DROP_SHIP_FLG
END CHANNEL_DROP_SHIP_FLG,
SUM(BKGS_MSR.DD_EXTENDED_HOLD_QUANTITY*BE.PRDT_FAMILY_ALLOCATION_PCT) EXTENDED_HOLD_QTY,
SUM(BKGS_MSR.DD_EXTENDED_QUANTITY*BE.PRDT_FAMILY_ALLOCATION_PCT) EXTENDED_QTY,
SUM(BKGS_MSR.TRADE_IN_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT) TRADE_IN_AMT,
BKGS_MSR.DV_REVENUE_RECOGNITION_FLG AS REVENUE_RECOGNITION_FLG,
BKGS_MSR.DV_NET_SPREAD_FLG AS NET_SPREAD_FLG,
BKGS_MSR.CORPORATE_BOOKINGS_FLG CORPORATE_BOOKINGS_FLG,
'NA' AS SERVICE_CATEGORY_CD,
SUM(BKGS_MSR.DD_COMP_US_LIST_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_LIST_PRICE_AMT,
SUM(BKGS_MSR.DD_COMP_US_HOLD_LIST_PRICE_AMT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_HOLD_LIST_PRICE_AMT,
SUM(BKGS_MSR.DD_COMP_US_HOLD_NET_PRICE_AMT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_HOLD_NET_PRICE_AMT,
SUM(BKGS_MSR.DD_COMP_US_HOLD_COST_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_HOLD_COST_AMT,
SUM(BKGS_MSR.DD_COMP_US_NET_PRICE_AMOUNT *BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_NET_PRICE_AMT,
CAST(0 AS DECIMAL(28, 7)) AS COMP_US_FX_NET_PRICE_AMT,
SUM(BKGS_MSR.DD_COMP_US_COST_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_COST_AMT,
SUM(BKGS_MSR.DD_COMP_US_STANDARD_PRICE_AMT*BE.PRDT_FAMILY_ALLOCATION_PCT) COMP_US_STANDARD_PRICE_AMT,
SUM(BKGS_MSR.DV_ANNUALIZED_US_NET_AMT*BE.PRDT_FAMILY_ALLOCATION_PCT) DV_ANNUALIZED_US_NET_AMT,
SUM(BKGS_MSR.DV_MULTIYEAR_US_NET_AMT*BE.PRDT_FAMILY_ALLOCATION_PCT) DV_MULTIYEAR_US_NET_AMT,
0 AS DV_AS_PENDING_BKGS_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.CANCEL_CODE, 'en-ci-rtrim') = 'Lost Order'
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_DEBKGS_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE, 'en-ci-rtrim') = 'ERP'
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_ORACLE_ACTUAL_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.DSV_FLG, 'en-ci-rtrim') = 'N' AND RTRIM( BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('POS', 'en-ci-rtrim'), COLLATE('POS_ADJ', 'en-ci-rtrim'))
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_POS_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.DSV_FLG, 'en-ci-rtrim') = 'Y' AND RTRIM( BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('POS', 'en-ci-rtrim'), COLLATE('POS_ADJ', 'en-ci-rtrim'))
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_DSV_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.DSV_FLG, 'en-ci-rtrim') = 'N' AND RTRIM( BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('AR', 'en-ci-rtrim'), COLLATE('SLS_ADJ', 'en-ci-rtrim'), COLLATE('XAAS', 'en-ci-rtrim'))
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_EIS_CM_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.ADJUSTMENT_CODE, 'en-ci-rtrim') LIKE 'LCLD%'
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_CLD_BKGS_NET_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.ADJUSTMENT_CODE, 'en-ci-rtrim') NOT LIKE 'LCLD%'
THEN DD_COMP_US_NET_PRICE_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_NON_CLD_BKGS_NET_AMT,
SUM(CASE
WHEN COLLATE(BKGS_MSR.ADJUSTMENT_CODE, 'en-ci-rtrim') NOT LIKE 'LCLD%'
THEN DD_COMP_US_COST_AMOUNT*BE.PRDT_FAMILY_ALLOCATION_PCT ELSE 0
END) DV_NON_CLD_BKGS_COST_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_NET_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_COST_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_TTL_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_FX_NET_AMT,
CAST(0 AS DECIMAL(28, 7)) AS BKGS_GROSS_MARGIN_FX_TTL_AMT,
BKG_CHNL_MSR.PARTNER_SITE_PARTY_KEY  PARTNER_PARTY_SITE_KEY,
BKG_CHNL_MSR.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
BKGS_MSR.DV_ATTRIBUTION_CD DV_ATTRIBUTION_CD,
DV_PRODUCT_KEY,
'UNKNOWN' AS BK_SERVICE_CATEGORY_ID,
'UNKNOWN' AS ALLOCATED_SERVC_GROUP_ID,
'UNKNOWN' AS BK_PRODUCT_SUBGROUP_ID,
DV_FMV_FLG,
BKGS_MSR.ADJUSTMENT_CODE AS BK_SALES_ADJ_CD,
/*ADDED ATTRIBUTE LOGIC AS PART OF DSV Q1FY16 BY */
BKGS_MSR.DSV_FLG,
'NA' AS SALES_MOTION_CD,
/* Added the below columns as part of  RO project  Q3FY17**/
BKGS_MSR.XCAT_FLG,
BKGS_MSR.BK_OFFER_TYPE_NAME,
BKGS_MSR.RECURRING_OFFER_FLG,
BKGS_MSR.ELA_FLG,
BKGS_MSR.DV_RECURRING_OFFER_CD,
/* MBR- ACQ Changes*/
BKGS_MSR.ACQUISITION_ORDER_ORIGIN_CD
FROM
{{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} BKGS_MSR
INNER JOIN
{{ source('raw', 'R_SALES_HIERARCHY') }} SHIER
ON SHIER.SALES_TERRITORY_KEY = BKGS_MSR.SALES_TERRITORY_KEY
INNER  JOIN
{{ source('raw', 'N_BKGS_CHNL_MEASURE') }} BKG_CHNL_MSR
ON  BKGS_MSR.BOOKINGS_MEASURE_KEY = BKG_CHNL_MSR.BOOKINGS_MEASURE_KEY
AND BKGS_MSR.BOOKINGS_PROCESS_DATE = BKG_CHNL_MSR.BOOKINGS_PROCESS_DATE
AND BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE = BKG_CHNL_MSR.BKGS_MEASURE_TRANS_TYPE_CODE
INNER JOIN
{{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} FD2Y
ON BKGS_MSR.BOOKINGS_PROCESS_DATE = FD2Y.CALENDAR_DATE
AND FD2Y.FISCAL_YEAR_AGE BETWEEN 0 AND 3
INNER JOIN
{{ source('raw', 'MT_BE_HIER_PRDT_FAMILY_ALLOC') }} BE
ON  BKGS_MSR.PRODUCT_KEY = BE.ITEM_KEY
AND BE.FISCAL_YEAR_QUARTER_NUMBER_INT = FD2Y.FISCAL_YEAR_QUARTER_NUMBER_INT
AND COLLATE( BE.BK_BUSINESS_ENTITY_TYPE_CD, 'en-ci-rtrim') = 'I'
WHERE
COLLATE( BKGS_MSR.DV_REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
AND COLLATE( BKGS_MSR.SERVICE_FLG, 'en-ci-rtrim') = 'N'
GROUP BY
FD2Y.FISCAL_YEAR_WEEK_NUM_INT,
FD2Y.FISCAL_YEAR_MONTH_INT,
BKGS_MSR.PRODUCT_KEY,
BKGS_MSR.SALES_TERRITORY_KEY,
BKGS_MSR.SALES_REP_NUMBER,
BKGS_MSR.WIPS_ORIGINATOR_ID_INT,
BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE,
BKGS_MSR.CANCEL_CODE,
BKGS_MSR.SALESREP_FLG,
BKGS_MSR.SERVICE_FLG,
BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG,
BKG_CHNL_MSR.CHANNEL_DROP_SHIP_FLG,
BKGS_MSR.DV_REVENUE_RECOGNITION_FLG,
BKGS_MSR.DV_NET_SPREAD_FLG,
BKGS_MSR.CORPORATE_BOOKINGS_FLG,
BKG_CHNL_MSR.PARTNER_SITE_PARTY_KEY,
BKG_CHNL_MSR.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
BKGS_MSR.DV_ATTRIBUTION_CD,
DV_PRODUCT_KEY,
DV_FMV_FLG,
BKGS_MSR.ADJUSTMENT_CODE,
BKGS_MSR.DSV_FLG  /*ADDED ATTRIBUTE LOGIC AS PART OF DSV Q1FY16 BY */,
BKGS_MSR.XCAT_FLG,
BKGS_MSR.BK_OFFER_TYPE_NAME,
BKGS_MSR.RECURRING_OFFER_FLG,
BKGS_MSR.ELA_FLG   ,
BKGS_MSR.DV_RECURRING_OFFER_CD,
BKGS_MSR.ACQUISITION_ORDER_ORIGIN_CD
{% endif %}